internal static class TimelineGroupTests
{
    static void Check(bool yes,string text){if(!yes)throw new Exception(text);}
    static Track Shot(string id,int lane){return new Track{id=id,name=id,kind="emitter",sprite="sprCherry",lane=lane,start=0,end=90,count=3,spread=0,interval=10,life=80,speed=2,x=160,y=150,advancedBullets=true};}
    static Track Event(string key,int frame){var t=new Track{id=key+frame,kind="control",lane=4,start=frame};EventPresets.ApplyPreset(t,key);return t;}
    static EditorState Fixture(){
        var a=Shot("a",1);a.spawnActions.Add(new BulletAction{type="spawn",templateId="te",start=1,spawnRepeat=30,maxGeneration=2});a.bulletActions.Add(new BulletAction{type="direction",start=2,duration=0,expressions=new Dictionary<string,string>{{"to","choose(0,30,60)"},{"from","choose(0,30,60)"}}});
        a.bulletActions.Add(new BulletAction{type="split",start=3,duration=0,templateId="te",count=2,childSpeed=1,maxGeneration=1});
        var root=new Track{id="ring",name="ring",kind="rod",shape="ring",sprite="sprCherry",lane=0,start=0,end=80,count=6,radius=40,x=240,y=170,color="#FFFFFF"};Motion.SetKey(root,"x",0,200);Motion.SetKey(root,"x",80,360);
        var host=new Track{id="host",kind="object",sprite="sprCherry",lane=3,start=0,end=50};host.spawnActions.Add(new BulletAction{type="spawn",templateId="tr",start=2});
        var tr=new Track{id="tr",name="tr",kind="rod",sprite="sprCherry",shape="star2",templateOnly=true,lane=7,start=100,end=120,count=5,radius=30};
        var te=Shot("te",8);te.templateOnly=true;te.start=100;te.end=130;te.count=2;te.interval=8;te.spawnActions.Clear();
        var alpha=Event("group-set",4);alpha.eventProperty="alpha";alpha.controlValue=.3;
        var copy=Event("group-copy",6);copy.expressions["controlValue"]="random_range(1,4)";copy.expressions["controlFrom"]="point_direction(source.x,source.y,x,y)+choose(0,90,180)";copy.eventCopyLife=16;
        var reset=Event("reset-motion",12);reset.eventRestoreBirth=false;reset.expressions["controlValue"]="random_range(2,5)";reset.expressions["controlFrom"]="choose(0,45,90)";reset.expressions["eventAcceleration"]="choose(0,.1)";
        var set=Event("group-set",15);set.eventGroup="B";set.controlValue=5;
        var hue=Event("group-set",17);hue.eventGroup="B";hue.eventProperty="color";hue.expressions["controlValue"]="choose(0,120,240)";var size=Event("group-set",18);size.eventProperty="scale";size.expressions["controlValue"]="choose(.5,1.5)";
        var clear=Event("group-clear",22);clear.end=25;
        var future=root.Snapshot();future.id="future";future.start=26;future.end=70;future.keyframes.Clear();future.lane=5;
        var copyB=Event("group-copy",30);copyB.eventGroup="B";copyB.controlValue=1;copyB.controlFrom=90;copyB.eventCopyLife=12;
        var s=new EditorState{duration=300,randomSeed=23077,tracks=new List<Track>{root,a,Shot("b",2),host,tr,te,alpha,copy,reset,set,hue,size,clear,future,copyB},timelineGroups=new List<TimelineGroup>{new TimelineGroup{id="A",name="Group A",color="#5887B8",lanes=new List<int>{0,1,3,4,5}},new TimelineGroup{id="B",name="Group B",color="#9B73B0",lanes=new List<int>{2}}}};var link=CopyGeneration.Apply(s,root);link.copyUp=false;link.copyDown=false;link.copyLeft=false;link.copyFacing="fixed";link.expressions["copyFacingAngle"]="choose(0,90)";Motion.Normalize(s);return s;
    }
    static object[] Rows(BulletWorld w){return w.bullets.Where(b=>!b.dead&&b.birth<=w.Frame).Select(b=>(object)new{source=b.source.id,birth=b.birth,index=b.index,generation=b.generation,x=b.x,y=b.y,speed=b.speed,direction=b.direction,scale=b.scale,alpha=b.alpha,kinematic=b.kinematic,clockShift=b.clockShift,group=b.scopeGroup,color=b.color.R+b.color.G*256+b.color.B*65536}).ToArray();}
    static void Simulation(string root){
        var s=Fixture();File.WriteAllText(Path.Combine(root,"scene.json"),Json.Write(s));var w=new BulletWorld(s);w.Seek(6);var copies=w.bullets.Where(b=>b.birth==6&&!b.kinematic).ToArray();Check(copies.Length==28,"Must copy 6 static members, 5 generated formation members, 3 source shots, 6 linked-copy members, 6 named-template split shots and 2 template shots exactly once: "+copies.Length);Check(copies.All(b=>b.scopeGroup=="A"&&b.behavior==null&&b.life==16),"Copies inherited behavior/lifetime or wrong group");Check(copies.Where(b=>b.source.id=="ring").All(b=>b.alpha==.3),"Formation appearance did not persist into snapshot");Check(copies.Select(b=>b.speed).Distinct().Count()>4&&copies.Where(b=>b.source.id=="a"||b.source.id=="te").All(b=>!Double.IsNaN(b.direction)),"Per-member random/choose sampling missing");w.Seek(7);Check(w.bullets.Count(b=>b.birth==6)==28,"Copy repeated outside trigger");w.Seek(22);Check(!w.bullets.Any(b=>b.scopeGroup=="A"&&b.birth<=22),"Group clear missed descendants");Check(w.bullets.Any(b=>b.scopeGroup=="B"),"Group clear leaked to other group");Check(!w.Templates.Visible(w.State.tracks.Single(t=>t.id=="ring")),"Cleared original formation reappeared");w.Seek(26);Check(w.Templates.Visible(w.State.tracks.Single(t=>t.id=="future")),"Clear suppressed future clip");w.Seek(30);Check(w.bullets.Any(b=>b.birth==30&&b.scopeGroup=="B"&&b.generation>0),"Explicit group override did not copy");w.Seek(270);string end=Json.Write(Rows(w));w.Seek(3);w.Seek(270);Check(end==Json.Write(Rows(w)),"Rewind not deterministic");
        var snap=s.Snapshot();snap.timelineGroups[0].lanes.Clear();snap.tracks.Single(t=>t.id=="a").bulletActions[0].expressions["to"]="1";Check(s.timelineGroups[0].lanes.Count>0&&s.tracks.Single(t=>t.id=="a").bulletActions[0].expressions["to"]!="1","Snapshot shares mutable group/action data");var json=Json.Read<EditorState>(Json.Write(s));Motion.Normalize(json);Check(TimelineGroups.Id(json.tracks.Single(t=>t.id=="a"))=="A","Save/load lost groups");TimelineEditing.Organize(json);Check(TimelineGroups.Id(json.tracks.Single(t=>t.id=="a"))=="A"&&TimelineGroups.Id(json.tracks.Single(t=>t.id=="b"))=="B","Organize mixed groups");
        var setAlpha=Event("group-set",0);setAlpha.eventProperty="alpha";setAlpha.controlValue=.4;EventPresets.Scale(setAlpha,2);Check(setAlpha.controlValue==.4,"FPS conversion changed opacity");var scaled=new BulletAction{type="speed",expressions=new Dictionary<string,string>{{"to","choose(2,4)"}}};ScalarExpressions.ScaleAction(scaled,2);double rate=RandomExpression.Evaluate(scaled.expressions["to"],1,"scale");Check(rate==1||rate==2,"Action formula units not scaled");
        Console.WriteLine("PASS: shared lanes, isolated group effects, complete formation/template copy, independent random motion, clear/future/rewind and snapshot/save/organize.");
    }
    static void CopyLifecycle(string root){
        var counts=new Dictionary<string,int>();
        foreach(string mode in BulletLifetime.Modes){
            var s=Fixture();var e=s.tracks.Single(t=>t.eventPreset=="group-copy"&&t.start==6);e.eventCopyDestroyOriginal=true;e.lifetimeMode=mode;e.eventCopyLife=2;e.controlValue=0;e.controlFrom=0;e.expressions.Clear();
            s.tracks.Add(new Track{id="outside",kind="rod",sprite="sprCherry",shape="ring",lane=11,start=0,end=40,count=3,x=1000,y=200,radius=20});s.timelineGroups[0].lanes.Add(11);
            s.tracks.Add(new Track{id="camera",kind="camera",lane=12,start=0,end=300,x=300,y=240,cameraZoom=2.5,angle=30});
            var room=Shot("room-life",13);room.start=room.end=0;room.count=1;room.life=1;room.speed=0;room.x=50;room.y=50;room.lifetimeMode="room";s.tracks.Add(room);
            var view=Shot("view-life",14);view.start=view.end=0;view.count=1;view.life=1;view.speed=120;view.x=300;view.y=240;view.lifetimeMode="view";s.tracks.Add(view);
            s.tracks.Single(t=>t.id=="te").lifetimeMode="room";Motion.Normalize(s);File.WriteAllText(Path.Combine(root,"copy-lifecycle-"+mode+".json"),Json.Write(s));
            var w=new BulletWorld(s);w.Seek(1);Check(w.bullets.Any(b=>b.source.id=="view-life"),"View lifetime used fixed age");w.Seek(2);Check(!w.bullets.Any(b=>b.source.id=="view-life"),"View lifetime ignored rotated camera boundary");
            w.Seek(6);counts[mode]=w.bullets.Count(b=>b.birth==6&&b.scopeGroup=="A");Check(!w.bullets.Any(b=>b.birth<6&&b.scopeGroup=="A"),"Original bullet survived replacement");var ring=w.State.tracks.Single(t=>t.id=="ring");Check(Enumerable.Range(0,ring.count).All(i=>!w.Templates.Visible(ring,i)),"Original held members reappeared");Check(w.bullets.Any(b=>b.scopeGroup=="B"),"Replacement destroyed another group");
            w.Seek(8);Check(mode=="fixed"?!w.bullets.Any(b=>b.birth==6):w.bullets.Any(b=>b.birth==6),"Copy lifetime mode did not control expiry");Check(w.bullets.Any(b=>b.source.id=="room-life"),"Room lifetime was capped by fixed life");
            w.Seek(10);Check(w.bullets.Any(b=>b.source.id=="a"&&b.birth==10),"Replacing existing bullets cancelled future emission");Check(!w.bullets.Any(b=>b.kinematic&&b.source.id=="ring"),"Linked original regenerated after replacement");
            w.Seek(205);w.Seek(5);w.Seek(6);Check(w.bullets.Count(b=>b.birth==6&&b.scopeGroup=="A")==counts[mode],"Replacement state lost on rewind");
            var saved=Json.Read<EditorState>(Json.Write(s));var restored=saved.tracks.Single(t=>t.id==e.id);Check(restored.eventCopyDestroyOriginal&&restored.lifetimeMode==mode,"Saved copy lifetime lost");var preset=TrackPreset.Capture("copy",new[]{e},50).Instantiate(50,100).Single();Check(preset.eventCopyDestroyOriginal&&preset.lifetimeMode==mode&&preset.eventCopyLife==4,"Preset/FPS lost copy settings");
        }
        Check(counts["fixed"]==31&&counts["room"]==28&&counts["view"]>0&&counts["view"]<counts["room"],"Birth boundary filtering is wrong: "+Json.Write(counts));
        Console.WriteLine("PASS: copy/replace fixed, room and rotated-view lifetime, immediate outside culling, source/template/link removal, future emission, rewind/save/preset/FPS. "+Json.Write(counts));
    }
    static void UI(string root){
        var s=Fixture();using(var timeline=new TimelineCanvas{State=s,Size=new Size(1000,600)}){using(var bmp=new Bitmap(1000,600)){timeline.DrawToBitmap(bmp,timeline.ClientRectangle);bmp.Save(Path.Combine(root,"group-colors.png"));}Check(TimelineGroups.Background(s.timelineGroups[0],false)!=TimelineGroups.Background(s.timelineGroups[1],false),"Group colors indistinct");}
        using(var sprites=new SpriteStore{Project=root})using(var stage=new StageCanvas{State=s,Room=new RoomData(),Sprites=sprites}){stage.SceneChanged();var render=(EditorState)typeof(StageCanvas).GetField("renderState",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(stage);Check(render.timelineGroups.Count==2&&render.timelineGroups[0]!=s.timelineGroups[0],"Background preview snapshot lost or shared group definitions");var world=new BulletWorld(render);world.Seek(6);Check(world.bullets.Count(b=>b.birth==6)==28,"Actual stage snapshot differs from preview simulation");}
        using(var form=new MainForm(root)){var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(MainForm).GetField("state",flags).SetValue(form,s);typeof(MainForm).GetField("document",flags).SetValue(form,new LoadData{state=s,room=new RoomData(),inventory=new Inventory{sprites=new[]{"sprCherry"},objects=new string[0],scripts=new string[0]}});var tl=(TimelineCanvas)typeof(MainForm).GetField("timeline",flags).GetValue(form);tl.State=s;tl.ActiveLane=1;typeof(MainForm).GetMethod("SelectTrack",flags).Invoke(form,new object[]{s.tracks.Single(t=>t.id=="a"),null});using(var menu=new ContextMenuStrip()){typeof(MainForm).GetMethod("CompactTrackContext",flags).Invoke(form,new object[]{menu});Check(menu.Items.Count<=12,"Track menu still too long");Check(menu.Items.Cast<ToolStripItem>().Any(i=>i.Text.Contains("组")),"Group assignment menu missing");}var evt=s.tracks.Single(t=>t.eventPreset=="reset-motion");typeof(MainForm).GetMethod("SelectTrack",flags).Invoke(form,new object[]{evt,null});var bag=(NativeProperties)((ParameterInspector)typeof(MainForm).GetField("properties",flags).GetValue(form)).SelectedObject;Check(bag!=null,"Event parameters missing");var fields=bag.GetProperties().Cast<ValueProperty>().ToArray();Check(fields.Where(p=>p.Name=="重设速度"||p.Name=="重设方向 / 度"||p.Name=="重设加速度 / 每帧").All(p=>p.Actions!=null&&p.Actions.SetExpression!=null),"Reset fields reject formulas");typeof(MainForm).GetMethod("SelectTrack",flags).Invoke(form,new object[]{s.tracks.Single(t=>t.id=="a"),null});typeof(MainForm).GetMethod("SetLaneGroup",flags).Invoke(form,new object[]{s.timelineGroups[1]});Check(TimelineGroups.Id(s.tracks.Single(t=>t.id=="a"))=="B","Lane grouping did not reassign all clips");typeof(MainForm).GetMethod("Undo",flags).Invoke(form,new object[]{false});var restored=(EditorState)typeof(MainForm).GetField("state",flags).GetValue(form);Check(TimelineGroups.Id(restored.tracks.Single(t=>t.id=="a"))=="A","Undo did not restore group");}
        Console.WriteLine("PASS: native group backgrounds and compact track context; reset event property UI.");
    }
    static void LifetimeUI(string root){
        var flags=BindingFlags.Instance|BindingFlags.NonPublic;var s=Fixture();
        using(var form=new MainForm(root)){
            typeof(MainForm).GetField("state",flags).SetValue(form,s);typeof(MainForm).GetField("document",flags).SetValue(form,new LoadData{state=s,room=new RoomData(),inventory=new Inventory{sprites=new[]{"sprCherry"},objects=new string[0],scripts=new string[0]}});((TimelineCanvas)typeof(MainForm).GetField("timeline",flags).GetValue(form)).State=s;
            Action<Track> select=t=>typeof(MainForm).GetMethod("SelectTrack",flags).Invoke(form,new object[]{t,null});Action refresh=()=>typeof(MainForm).GetMethod("ShowProperties",flags).Invoke(form,null);Func<NativeProperties> bag=()=>((ParameterInspector)typeof(MainForm).GetField("properties",flags).GetValue(form)).SelectedObject as NativeProperties;
            var e=s.tracks.Single(t=>t.eventPreset=="group-copy"&&t.start==6);select(e);
            foreach(string mode in BulletLifetime.Modes){var field=bag().GetProperties()["副本寿命模式"];Check(field!=null&&field.Converter.GetStandardValues().Count==3,"Copy lifetime picker missing modes");field.SetValue(bag(),BulletLifetime.ModeNames[Array.IndexOf(BulletLifetime.Modes,mode)]);refresh();Check(e.lifetimeMode==mode,"Lifetime UI did not write model");Check((bag().GetProperties()["副本寿命 / 帧"]!=null)==(mode=="fixed"),"Fixed lifetime shown for boundary mode");Check((bag().GetProperties()["出界余量 / 像素"]!=null)==(mode!="fixed"),"Boundary margin missing");}
            Check(!e.eventCopyDestroyOriginal,"Old copy changed its default replacement behavior");bag().GetProperties()["是否销毁原弹幕"].SetValue(bag(),true);Check(e.eventCopyDestroyOriginal,"Replacement checkbox did not write model");typeof(MainForm).GetMethod("Undo",flags).Invoke(form,new object[]{false});s=(EditorState)typeof(MainForm).GetField("state",flags).GetValue(form);Check(!s.tracks.Single(t=>t.id==e.id).eventCopyDestroyOriginal,"Undo did not restore replacement setting");
            select(s.tracks.Single(t=>t.id=="a"));Check(bag().GetProperties()["寿命模式"].Category==bag().GetProperties()["寿命"].Category,"Emitter lifetime is separated from its mode");select(s.tracks.Single(t=>t.id=="ring"));Check(bag().GetProperties()["寿命模式"].Category==bag().GetProperties()["释放后寿命 / 帧"].Category,"Released lifetime is separated from its mode");
            var source=s.tracks.Single(t=>t.id=="a");var action=GenerationPresets.Apply(s,source,"random-360");var shot=s.tracks.Single(t=>t.id==action.templateId);var quick=new NativeProperties();GenerationPresets.Fields(quick,s,source,action,change=>change());quick.GetProperties()["寿命模式"].SetValue(quick,BulletLifetime.ModeNames[2]);quick=new NativeProperties();GenerationPresets.Fields(quick,s,source,action,change=>change());Check(shot.lifetimeMode=="view"&&quick.GetProperties()["固定寿命 / 帧"]==null&&quick.GetProperties()["出界余量 / 像素"]!=null,"Generated bullet lifetime entry is inconsistent");
        }
        Console.WriteLine("PASS: copy lifetime modes/replacement/Undo and consistent emitter, release and generation lifetime settings.");
    }
    [STAThread]static int Main(string[] args){try{if(args[0]=="--samples"){var s=Json.Read<EditorState>(File.ReadAllText(args[1]));Motion.Normalize(s);var w=new BulletWorld(s);var rows=new Dictionary<string,object>();foreach(int frame in args[2].Split(',').Select(Int32.Parse)){w.Seek(frame);rows[frame.ToString()]=Rows(w);}File.WriteAllText(args[3],Json.Write(rows));return 0;}Application.EnableVisualStyles();Simulation(args[0]);CopyLifecycle(args[0]);UI(args[0]);LifetimeUI(args[0]);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
